'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isAlmostSameValuef = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var j1 = require( './../lib' );


// FIXTURES //

var smaller = require( './fixtures/julia/smaller.json' );
var smallPositive = require( './fixtures/julia/small_positive.json' );
var smallNegative = require( './fixtures/julia/small_negative.json' );
var mediumPositive = require( './fixtures/julia/medium_positive.json' );
var largePositive = require( './fixtures/julia/large_positive.json' );
var veryLargePositive = require( './fixtures/julia/very_large_positive.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof j1, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function evaluates the Bessel function of the first kind of order one (smaller positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = smaller.expected;
	x = smaller.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 5 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the Bessel function of the first kind of order one (small positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = smallPositive.expected;
	x = smallPositive.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 8 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the Bessel function of the first kind of order one (small negative values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = smallNegative.expected;
	x = smallNegative.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 8 ), true, 'returns expected value' );
	}
	t.end();
});

// NOTE: Higher ULP tolerances for the asymptotic branch (w > 8) are due to reduced float32 precision in sin/cos evaluation near the periodic zeros of J1, where near-zero values inflate relative ULP. // eslint-disable-line max-len

tape( 'the function evaluates the Bessel function of the first kind of order one (medium positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = mediumPositive.expected;
	x = mediumPositive.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 419 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the Bessel function of the first kind of order one (large positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = largePositive.expected;
	x = largePositive.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 591 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function evaluates the Bessel function of the first kind of order one (very large positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = veryLargePositive.expected;
	x = veryLargePositive.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValuef( y, e, 251 ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v = j1( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0.0` if provided `+infinity`', function test( t ) {
	var v = j1( PINF );
	t.strictEqual( v, 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0.0` if provided `-infinity`', function test( t ) {
	var v = j1( NINF );
	t.strictEqual( v, 0.0, 'returns expected value' );
	t.end();
});

tape( 'the function returns `0.0` if provided `0.0`', function test( t ) {
	var v = j1( 0.0 );
	t.strictEqual( isPositiveZerof( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function is an odd function (f(x) = -f(-x))', function test( t ) {
	var x;
	var y;
	var i;

	x = smallPositive.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		t.strictEqual( y, -j1( -f32( x[ i ] ) ), 'returns expected value' );
	}
	t.end();
});
